probe.output:
extends SceneTree

func _initialize() -> void:
	call_deferred("_run")

func _frames() -> void:
	for frame in range(8):
		await process_frame

func _button(node: Node, text: String) -> Button:
	if node is Button and node.text == text:
		return node
	for child in node.get_children():
		var found := _button(child, text)
		if found != null:
			return found
	return null

func _tap(control: Control) -> void:
	var point: Vector2 = control.get_viewport().get_screen_transform() * control.get_global_transform_with_canvas() * (control.size * 0.5)
	for pressed in [true, false]:
		var event := InputEventScreenTouch.new()
		event.index = 4
		event.position = point
		event.pressed = pressed
		Input.parse_input_event(event)
		Input.flush_buffered_events()
		await process_frame
	await _frames()

func _run() -> void:
	root.size = Vector2i(2400, 1080)
	root.gui_embed_subwindows = true
	root.get_node("HostBridge")._options = {"displayDensity": 2.625, "reduceAnimations": true, "soundEnabled": false}
	root.get_node("SceneRouter").launch_options = {"childKey": "build_dialog_before_unique", "buildSlot": 1}
	var game = load("res://scenes/creative/build_world.tscn").instantiate()
	root.add_child(game)
	current_scene = game
	await _frames()
	var open := _button(game, "Welten (6)")
	var parent := open.get_parent()
	while parent != null:
		if parent is ScrollContainer:
			parent.ensure_control_visible(open)
		parent = parent.get_parent()
	await _frames()
	await _tap(open)
	var dialog: Window
	for child in game.get_children():
		if child is Window:
			dialog = child
	print("[BuildDialogBefore] opened_by_real_touch=", is_instance_valid(dialog), " slot=", game.slot)
	if is_instance_valid(dialog):
		print("[BuildDialogBefore] size=", dialog.size, " viewport=", dialog.get_visible_rect(), " min=", dialog.min_size, " position=", dialog.position)
		await _tap(_button(dialog, "Welt 2 · neue Insel"))
		print("[BuildDialogBefore] selected_by_real_touch=", game.slot == 2, " remaining_dialog=", is_instance_valid(dialog))
	game.queue_free()
	await _frames()
	quit()

extends "/tmp/lumo_build_dialog_before.gd"

func _hits(node: Node, point: Vector2) -> void:
	if node is Button and node.is_visible_in_tree():
		var caption: String = node.text
		node.pressed.connect(func(): print("[ShortToolbar] actual_pressed=", caption))
		if node.get_global_rect().has_point(point):
			print("[ShortToolbar] rectangle_overlap=", caption, " rect=", node.get_global_rect(), " path=", node.get_path())
	for child in node.get_children():
		_hits(child, point)

func _run() -> void:
	root.size = Vector2i(640, 320)
	Input.emulate_touch_from_mouse = true
	root.get_node("HostBridge")._options = {"displayDensity": 1.0, "reduceAnimations": true, "soundEnabled": false}
	root.get_node("SceneRouter").launch_options = {"childKey": "short_toolbar_probe"}
	var game = load("res://scenes/creative/build_world.tscn").instantiate()
	root.add_child(game)
	await _frames()
	var button := _button(game, "Vorlagen")
	var parent := button.get_parent()
	while parent != null:
		if parent is ScrollContainer:
			parent.ensure_control_visible(button)
		parent = parent.get_parent()
	await _frames()
	_hits(game, button.get_global_rect().get_center())
	print("[ShortToolbar] intended=Vorlagen actual_rect=", button.get_global_rect())
	await _tap(button)
	print("[ShortToolbar] dialog_open=", is_instance_valid(game.choice_window))
	game.queue_free()
	await _frames()
	quit()
